    	UPDATE

    		invn


    		lens_invn


    		clens_invn


    		clens_acc_invn

    	SET
    		cnt = cnt + #{prdctCnt}
   		WHERE
			prdct_id =#{prdctId}
			AND shop_id = #{shopId}

    	UPDATE

    		invn


    		lens_invn


    		clens_invn


    		clens_acc_invn

    	SET
    		cnt = cnt -  #{prdctCnt}
   		WHERE
			prdct_id =#{prdctId}
			AND shop_id = #{shopId}

